{
  "episode_situation": "周一晚上，用户下班后独自在租住的房间里，因准备在本地长期工作，想在请假跑窗口前先弄懂首次申领居住证的通用规则。他手边有本人身份证和租赁合同，但只听同事提过居住登记或居住时长可能是条件，尚未核实当地的具体口径。他没有当地办事指南，也未说明城市和区县，因此办理地点、材料清单、补正方式及电子证适用范围仍需按当地规定确认。眼下最关心的是先听明白一般条件、常见材料和流程，再判断材料不齐能否先交，并区分电子证与实体证在领取、出示及具体场景认可上的常见差别。",
  "task_reference_data": [],
  "environment_audio": "右后方约两米处有落地扇持续低速运转，机械风声平稳而轻微。房间其余位置较安静，风扇声偶尔随摆头产生小幅强弱变化。",
  "estimated_snr_db": 30,
  "constraints": [
    {
      "constraint_id": "C01",
      "text": "先说明首次申领居住证的一般规则，不把任何城市的具体政策当作全国统一规定。",
      "kind": "hard"
    },
    {
      "constraint_id": "C02",
      "text": "涉及办理条件、材料清单、受理地点、补正方式以及电子证适用范围时，应区分常见做法与需要向当地经办机构核实的事项。",
      "kind": "hard"
    },
    {
      "constraint_id": "C03",
      "text": "解释尽量使用易懂的日常表达，便于不熟悉政务办理流程的用户逐项确认。",
      "kind": "soft"
    }
  ],
